$cp=[pscustomobject]@{Id=$checkpoint;Name=$prepared.outcomeCheckpointName;VMId=$prepared.vmId;State='Off';MemoryStartup=8GB;DynamicMemoryEnabled=$false};Assert-RetainedProbeCheckpoint $cp $checkpoint $cp.Name;$script:checks++
foreach($field in $cp.PSObject.Properties.Name){$b=Clone $cp;$b.$field=if($field -ceq 'DynamicMemoryEnabled'){$true}else{'wrong'};Reject {Assert-RetainedProbeCheckpoint $b $checkpoint $cp.Name} 'Wrong checkpoint accepted.'}
$b=Clone $cp;$b.Id=[guid]::Empty.ToString('D');Reject {Assert-RetainedProbeCheckpoint $b $b.Id $cp.Name} 'Empty checkpoint identity accepted.'
