}
$many=@(Entry pair.json 1);for($i=0;$i -lt 10;$i++){$many+=Entry ('query-'+$i.ToString('D3')+'.bin') 2MB};Reject {Assert-RetainedProbeArtifacts $many inspection} 'Inspection aggregate exceeded.'
